updateTime() {
  var now = new Date()
  var h = now.getHours().toString().padStart(2, '0')
  var m = now.getMinutes().toString().padStart(2, '0')
  this.time = h + ':' + m
},

// 屏幕形态/分辨率动态安全偏移：避免顶部时间被系统状态栏遮挡。
// 物理安全偏移按实测微调（物理像素）；换算为设计 px：设计px = N × 300 ÷ screenWidth
adjustForScreen() {
  var self = this
  device.getInfo({
    success: function(data) {
      var screenWidth = data.screenWidth
      var shape = data.screenShape
      if (!screenWidth) return
      var safeTopPx = 0 // 物理安全偏移（物理像素，按实测微调）
      var base = 28
      if (shape === 'pill-shaped') {
        safeTopPx = 12
        base = 30
      } else if (shape === 'circle') {
        safeTopPx = 10
        base = 20
      }
      var padTop = safeTopPx > 0 ? Math.round(safeTopPx * 300 / screenWidth) : 0
      self.topBarPadTop = padTop
      self.statusbarHeight = base + padTop
    }
  })
},

